                "loaded.fair": "Fair: calls and games may stutter while something is downloading.",
                "loaded.bad": "High (bufferbloat): the connection lags badly when busy. A router with smart queue management (SQM) can help.",
                "clk.now": "Time now",
                "clk.elapsed": "Test time",
                "off.title": "No internet access",
