                "svc.probe": "Reachability check",
                "svc.open": "Open {name}",
                "svc.note": "\"Reachability check\" means this browser could or could not open the site. It is not an official status, and ad blockers or a network block can also cause \"Can''t reach\".",
                "act.share": "Share result",
                "act.save": "Save result",
                "act.saved": "Saved",
                "act.image": "Download image",
                "act.copy": "Copy text",
                "act.copied": "Copied",
                "share.title": "My internet speed",
                "share.text": "My internet speed: {down} download, {up} upload, {ping} ms ping. Test yours free:",
                "share.whatsapp": "WhatsApp",
                "share.facebook": "Facebook",
                "share.x": "X",
                "share.telegram": "Telegram",
                "share.menu": "Share on",
                "hist.title": "Saved results",
                "hist.empty": "No saved results yet. Run a test and press \"Save result\".",
                "hist.note": "Results are stored only in this browser. Nothing is sent to a server.",
                "hist.clear": "Clear all",
                "hist.delete": "Delete",
                "hist.item": "{down} down, {up} up, {ping} ms ping, {jitter} ms jitter",
                "info.h2.intro": "Free internet speed test: check your download, upload and ping",
                "info.intro": "This free internet speed test shows how fast your connection really is in about 25 seconds. Press Start speed test and it measures your download speed, upload speed, ping and jitter against our own speed test server. It works on any phone, tablet or computer, on Wi-Fi, mobile data or a cable, and you never need to sign up.",
                "info.h2.mean": "What the results mean",
                "info.mean.1": "Download speed (Mbps): how quickly data reaches you. It controls video streaming, web pages, app updates and file downloads.",
                "info.mean.2": "Upload speed (Mbps): how quickly you send data. It matters for video calls, cloud backups, sharing large files and live streaming.",
                "info.mean.3": "Ping (ms): the delay between your device and a server. Lower is better, and under 20 ms is excellent for gaming and calls.",
                "info.mean.4": "Jitter (ms): how much the ping changes. Lower is better, and steady jitter means smooth calls and games.",
                "info.h2.good": "What is a good internet speed?",
                "info.good": "As a rough guide, 5 to 10 Mbps handles one HD video stream, 25 Mbps suits a small household, and 100 Mbps or more is comfortable for several people streaming, working from home and gaming at once. Video calls need a steady upload speed of a few Mbps, so a fast download alone does not guarantee a good call.",
                "info.h2.accurate": "How to get the most accurate speed test result",
                "info.acc.1": "Pause downloads, streaming and video calls on every device on your network.",
                "info.acc.2": "Move close to your router, or connect a device with a cable.",
                "info.acc.3": "Close other browser tabs and turn off any VPN.",
                "info.acc.4": "Run the test two or three times and compare the results.",
                "info.h2.fix": "How to fix slow internet",
                "info.fix.1": "Restart your router and modem, then wait two minutes.",
                "info.fix.2": "Place the router in an open, central spot, away from walls and appliances.",
                "info.fix.3": "Switch to the 5 GHz Wi-Fi band for higher speed at short range.",
                "info.fix.4": "Disconnect devices you are not using, and pause large background updates.",
                "info.fix.5": "Update the router firmware, and replace an old router if it is several years old.",
                "info.fix.6": "If speeds stay far below your plan on a cable connection, contact your internet provider.",
                "info.h2.faq": "Frequently asked questions",
                "faq.1.q": "How accurate is this internet speed test?",
                "faq.1.a": "It measures against our own speed test server, so it shows your real-world speed to that server over the public internet. Results can vary slightly between runs because your connection, Wi-Fi signal and other devices on your network change from moment to moment. Run it two or three times and compare.",
                "faq.2.q": "What is a good internet speed?",
                "faq.2.a": "For most homes, 25 to 100 Mbps download is enough for HD streaming, video calls and browsing. Households with many devices, 4K streaming or large downloads benefit from 100 to 500 Mbps. Upload matters for video calls, cloud backups and live streaming, so aim for at least 10 Mbps.",
                "faq.3.q": "Why is my speed lower than what my provider advertises?",
                "faq.3.a": "Providers advertise the best-case speed on a wired connection. Wi-Fi distance, walls, router age, busy evening hours, other devices and a congested network can all reduce what you actually get. Testing with a cable connected to your router shows the true speed of your plan.",
                "faq.4.q": "What is the difference between download and upload speed?",
                "faq.4.a": "Download speed is how fast data comes to your device, which affects streaming, browsing and downloading files. Upload speed is how fast data leaves your device, which affects video calls, sending large files and posting videos.",
                "faq.5.q": "What is ping and what is a good ping?",
                "faq.5.a": "Ping, also called latency, is the time in milliseconds for data to travel to a server and back. Under 20 ms is excellent, 20 to 50 ms is good for gaming and calls, and above 100 ms can feel laggy.",
                "faq.6.q": "What is jitter?",
                "faq.6.a": "Jitter is how much your ping changes from one moment to the next. Low jitter means a steady connection. High jitter causes choppy video calls, voice dropouts and online game lag even when your download speed is high.",
                "faq.7.q": "Is this speed test free?",
                "faq.7.a": "Yes. It is completely free, needs no signup and works on phones, tablets and computers in any modern browser.",
                "faq.8.q": "Does the test use a lot of data?",
                "faq.8.a": "A full test downloads and uploads test data for about 25 seconds, so it can use a noticeable amount of data on a fast connection. If you are on a limited mobile plan, run it on Wi-Fi or sparingly.",
                "seo.home.title": "Internet Speed Test: Check Download, Upload and Ping (Free)",
                "seo.home.desc": "Free internet speed test. Check your download speed, upload speed, ping and jitter in 25 seconds. Works on phone and PC, no signup. Learn what a good speed is.",
                "unit.gbps": "Gbps",
                "unit.gbps_down": "Gbps download",
                "unit.gbps_up": "Gbps upload"
            }',
