                "hist.clear": "सब हटाएं",
                "hist.delete": "हटाएं",
                "hist.item": "{down} डाउनलोड, {up} अपलोड, {ping} ms पिंग, {jitter} ms जिटर",
                "info.h2.intro": "मुफ़्त इंटरनेट स्पीड टेस्ट: डाउनलोड, अपलोड और पिंग जांचें",
                "info.intro": "यह मुफ़्त इंटरनेट स्पीड टेस्ट लगभग 25 सेकंड में बता देता है कि आपका कनेक्शन असल में कितना तेज़ है। \"स्पीड टेस्ट शुरू करें\" दबाएं, और यह हमारे अपने स्पीड टेस्ट सर्वर के साथ आपकी डाउनलोड स्पीड, अपलोड स्पीड, पिंग और जिटर नापता है। यह किसी भी फ़ोन, टैबलेट या कंप्यूटर पर, Wi-Fi, मोबाइल डेटा या केबल पर चलता है, और साइन अप की ज़रूरत नहीं है।",
                "info.h2.mean": "नतीजों का मतलब",
                "info.mean.1": "डाउनलोड स्पीड (Mbps): डेटा आप तक कितनी तेज़ी से पहुंचता है। वीडियो स्ट्रीमिंग, वेब पेज, ऐप अपडेट और फ़ाइल डाउनलोड इसी पर निर्भर करते हैं।",
                "info.mean.2": "अपलोड स्पीड (Mbps): आप कितनी तेज़ी से डेटा भेज पाते हैं। वीडियो कॉल, क्लाउड बैकअप, बड़ी फ़ाइलें भेजने और लाइव स्ट्रीमिंग के लिए यह ज़रूरी है।",
                "info.mean.3": "पिंग (ms): आपके डिवाइस और सर्वर के बीच की देरी। कम होना बेहतर है, और 20 ms से कम गेमिंग और कॉल के लिए बहुत अच्छा है।",
                "info.mean.4": "जिटर (ms): पिंग में कितना बदलाव आता है। कम होना बेहतर है, और स्थिर जिटर का मतलब है साफ़ कॉल और स्मूद गेम।",
                "info.h2.good": "अच्छी इंटरनेट स्पीड कितनी होती है?",
                "info.good": "मोटे तौर पर, 5 से 10 Mbps में एक HD वीडियो चलता है, 25 Mbps छोटे परिवार के लिए ठीक है, और 100 Mbps या ज़्यादा में कई लोग एक साथ स्ट्रीमिंग, घर से काम और गेमिंग आराम से कर सकते हैं। वीडियो कॉल के लिए कुछ Mbps की स्थिर अपलोड स्पीड चाहिए, इसलिए सिर्फ़ तेज़ डाउनलोड से अच्छी कॉल की गारंटी नहीं होती।",
                "info.h2.accurate": "सबसे सही स्पीड टेस्ट नतीजा कैसे पाएं",
                "info.acc.1": "अपने नेटवर्क के हर डिवाइस पर डाउनलोड, स्ट्रीमिंग और वीडियो कॉल रोक दें।",
                "info.acc.2": "राउटर के पास जाएं, या किसी डिवाइस को केबल से जोड़ें।",
                "info.acc.3": "ब्राउज़र के दूसरे टैब बंद करें और VPN बंद कर दें।",
                "info.acc.4": "टेस्ट दो या तीन बार चलाएं और नतीजों की तुलना करें।",
                "info.h2.fix": "धीमे इंटरनेट को कैसे ठीक करें",
                "info.fix.1": "अपना राउटर और मॉडेम रीस्टार्ट करें, फिर दो मिनट रुकें।",
                "info.fix.2": "राउटर को खुली, बीच की जगह पर रखें, दीवारों और बिजली के उपकरणों से दूर।",
                "info.fix.3": "कम दूरी पर ज़्यादा स्पीड के लिए 5 GHz Wi-Fi बैंड पर जाएं।",
                "info.fix.4": "जो डिवाइस इस्तेमाल में नहीं हैं उन्हें डिस्कनेक्ट करें, और बैकग्राउंड के बड़े अपडेट रोक दें।",
                "info.fix.5": "राउटर का फ़र्मवेयर अपडेट करें, और अगर राउटर कई साल पुराना है तो बदल दें।",
                "info.fix.6": "अगर केबल कनेक्शन पर भी स्पीड आपके प्लान से काफ़ी कम रहती है, तो अपने इंटरनेट प्रोवाइडर से संपर्क करें।",
                "info.h2.faq": "अक्सर पूछे जाने वाले सवाल",
                "faq.1.q": "यह इंटरनेट स्पीड टेस्ट कितना सही है?",
                "faq.1.a": "यह हमारे अपने स्पीड टेस्ट सर्वर के साथ नापता है, इसलिए यह सार्वजनिक इंटरनेट पर उस सर्वर तक आपकी असली स्पीड दिखाता है। हर बार के नतीजों में थोड़ा फ़र्क़ हो सकता है, क्योंकि आपका कनेक्शन, Wi-Fi सिग्नल और नेटवर्क के दूसरे डिवाइस पल-पल बदलते रहते हैं। इसे दो या तीन बार चलाकर तुलना करें।",
                "faq.2.q": "अच्छी इंटरनेट स्पीड कितनी होती है?",
                "faq.2.a": "ज़्यादातर घरों के लिए 25 से 100 Mbps डाउनलोड HD स्ट्रीमिंग, वीडियो कॉल और ब्राउज़िंग के लिए काफ़ी है। जिन घरों में कई डिवाइस हैं, 4K स्ट्रीमिंग होती है या बड़े डाउनलोड होते हैं, उन्हें 100 से 500 Mbps से फ़ायदा होता है। वीडियो कॉल, क्लाउड बैकअप और लाइव स्ट्रीमिंग के लिए अपलोड भी मायने रखता है, इसलिए कम से कम 10 Mbps रखें।",
                "faq.3.q": "मेरी स्पीड प्रोवाइडर के बताए से कम क्यों है?",
                "faq.3.a": "प्रोवाइडर केबल कनेक्शन पर सबसे अच्छी स्थिति की स्पीड बताते हैं। Wi-Fi की दूरी, दीवारें, राउटर की उम्र, शाम की भीड़, दूसरे डिवाइस और भीड़ वाला नेटवर्क, सब असली स्पीड घटा सकते हैं। राउटर से केबल जोड़कर टेस्ट करने पर आपके प्लान की असली स्पीड दिखती है।",
                "faq.4.q": "डाउनलोड और अपलोड स्पीड में क्या फ़र्क़ है?",
                "faq.4.a": "डाउनलोड स्पीड बताती है कि डेटा आपके डिवाइस तक कितनी तेज़ी से आता है, जिसका असर स्ट्रीमिंग, ब्राउज़िंग और फ़ाइल डाउनलोड पर पड़ता है। अपलोड स्पीड बताती है कि डेटा आपके डिवाइस से कितनी तेज़ी से जाता है, जिसका असर वीडियो कॉल, बड़ी फ़ाइलें भेजने और वीडियो पोस्ट करने पर पड़ता है।",
                "faq.5.q": "पिंग क्या है और अच्छी पिंग कितनी होती है?",
                "faq.5.a": "पिंग, जिसे लेटेंसी भी कहते हैं, वह समय है (मिलीसेकंड में) जो डेटा को सर्वर तक जाने और वापस आने में लगता है। 20 ms से कम बहुत अच्छी है, 20 से 50 ms गेमिंग और कॉल के लिए अच्छी है, और 100 ms से ऊपर सुस्ती महसूस हो सकती है।",
                "faq.6.q": "जिटर क्या है?",
                "faq.6.a": "जिटर बताता है कि आपकी पिंग एक पल से दूसरे पल में कितनी बदलती है। कम जिटर का मतलब है स्थिर कनेक्शन। ज़्यादा जिटर से वीडियो कॉल अटकती है, आवाज़ कटती है और ऑनलाइन गेम में लैग आता है, भले ही डाउनलोड स्पीड ज़्यादा हो।",
                "faq.7.q": "क्या यह स्पीड टेस्ट मुफ़्त है?",
                "faq.7.a": "हां। यह पूरी तरह मुफ़्त है, साइन अप की ज़रूरत नहीं है, और किसी भी आधुनिक ब्राउज़र में फ़ोन, टैबलेट और कंप्यूटर पर चलता है।",
                "faq.8.q": "क्या टेस्ट में बहुत डेटा खर्च होता है?",
                "faq.8.a": "पूरा टेस्ट लगभग 25 सेकंड तक टेस्ट डेटा डाउनलोड और अपलोड करता है, इसलिए तेज़ कनेक्शन पर काफ़ी डेटा खर्च हो सकता है। अगर आपका मोबाइल प्लान सीमित है, तो इसे Wi-Fi पर या कम बार चलाएं।",
                "seo.home.title": "इंटरनेट स्पीड टेस्ट: डाउनलोड, अपलोड और पिंग जांचें (मुफ़्त)",
                "seo.home.desc": "मुफ़्त इंटरनेट स्पीड टेस्ट। 25 सेकंड में अपनी डाउनलोड स्पीड, अपलोड स्पीड, पिंग और जिटर जांचें। फ़ोन और पीसी पर चलता है, साइन अप नहीं चाहिए। जानें कि अच्छी स्पीड कितनी होती है।",
                "unit.gbps": "Gbps",
                "unit.gbps_down": "Gbps डाउनलोड",
                "unit.gbps_up": "Gbps अपलोड"
