                "info.intro": "يُظهر لك اختبار سرعة الإنترنت المجاني هذا مدى سرعة اتصالك الفعلية خلال نحو 25 ثانية. اضغط \"ابدأ اختبار السرعة\" وسيقيس سرعة التنزيل وسرعة الرفع وزمن الاستجابة والاهتزاز مع خادم اختبار السرعة الخاص بنا. يعمل على أي هاتف أو جهاز لوحي أو حاسوب، عبر Wi-Fi أو بيانات الجوال أو الكابل، ولا يتطلب إنشاء حساب.",
                "info.h2.mean": "ماذا تعني النتائج",
                "info.mean.1": "سرعة التنزيل (Mbps): مدى سرعة وصول البيانات إليك. تتحكم في بث الفيديو وتحميل صفحات الويب وتحديث التطبيقات وتنزيل الملفات.",
                "info.mean.2": "سرعة الرفع (Mbps): مدى سرعة إرسالك للبيانات. تهم في مكالمات الفيديو والنسخ الاحتياطي السحابي ومشاركة الملفات الكبيرة والبث المباشر.",
                "info.mean.3": "زمن الاستجابة (ms): التأخير بين جهازك والخادم. الأقل أفضل، وأقل من 20 ms ممتاز للألعاب والمكالمات.",
                "info.mean.4": "الاهتزاز (ms): مقدار تغيّر زمن الاستجابة. الأقل أفضل، والاهتزاز الثابت يعني مكالمات وألعابًا سلسة.",
                "info.h2.good": "ما هي سرعة الإنترنت الجيدة؟",
                "info.good": "كدليل تقريبي، تكفي سرعة من 5 إلى 10 Mbps لبث فيديو واحد بجودة HD، وتناسب سرعة 25 Mbps أسرة صغيرة، وتريح سرعة 100 Mbps أو أكثر عدة أشخاص يبثون ويعملون من المنزل ويلعبون في الوقت نفسه. تحتاج مكالمات الفيديو إلى سرعة رفع ثابتة تبلغ بضعة Mbps، لذا فإن التنزيل السريع وحده لا يضمن مكالمة جيدة.",
                "info.h2.accurate": "كيف تحصل على أدق نتيجة لاختبار السرعة",
                "info.acc.1": "أوقف التنزيلات والبث ومكالمات الفيديو على كل جهاز في شبكتك.",
                "info.acc.2": "اقترب من الراوتر، أو صِل جهازًا به بكابل.",
                "info.acc.3": "أغلق علامات تبويب المتصفح الأخرى وأوقف أي VPN.",
                "info.acc.4": "كرر الاختبار مرتين أو ثلاث مرات وقارن النتائج.",
                "info.h2.fix": "كيف تعالج بطء الإنترنت",
                "info.fix.1": "أعد تشغيل الراوتر والمودم، ثم انتظر دقيقتين.",
                "info.fix.2": "ضع الراوتر في مكان مفتوح ومركزي، بعيدًا عن الجدران والأجهزة.",
                "info.fix.3": "انتقل إلى نطاق Wi-Fi بتردد 5 GHz للحصول على سرعة أعلى عن قرب.",
