                "info.fix.6": "إذا بقيت السرعة أقل بكثير من باقتك على اتصال الكابل، فتواصل مع مزوّد الإنترنت.",
                "info.h2.faq": "الأسئلة الشائعة",
                "faq.1.q": "ما مدى دقة اختبار سرعة الإنترنت هذا؟",
                "faq.1.a": "يقيس مع خادم اختبار السرعة الخاص بنا، فيُظهر سرعتك الفعلية نحو هذا الخادم عبر الإنترنت العام. قد تختلف النتائج قليلًا بين مرة وأخرى لأن اتصالك وإشارة Wi-Fi والأجهزة الأخرى في شبكتك تتغير من لحظة إلى أخرى. أعد الاختبار مرتين أو ثلاث وقارن.",
                "faq.2.q": "ما هي سرعة الإنترنت الجيدة؟",
                "faq.2.a": "في معظم المنازل، تكفي سرعة تنزيل من 25 إلى 100 Mbps للبث بجودة HD ومكالمات الفيديو والتصفح. وتستفيد المنازل التي فيها أجهزة كثيرة أو بث 4K أو تنزيلات كبيرة من 100 إلى 500 Mbps. وتهم سرعة الرفع في مكالمات الفيديو والنسخ الاحتياطي السحابي والبث المباشر، لذا استهدف 10 Mbps على الأقل.",
                "faq.3.q": "لماذا سرعتي أقل مما يعلنه مزوّد الخدمة؟",
                "faq.3.a": "يعلن المزوّدون عن أفضل سرعة ممكنة على اتصال سلكي. يمكن لبُعد Wi-Fi والجدران وعمر الراوتر وساعات الذروة المسائية والأجهزة الأخرى والشبكة المزدحمة أن تقلل ما تحصل عليه فعلًا. الاختبار بكابل موصول بالراوتر يُظهر السرعة الحقيقية لباقتك.",
                "faq.4.q": "ما الفرق بين سرعة التنزيل وسرعة الرفع؟",
                "faq.4.a": "سرعة التنزيل هي مدى سرعة وصول البيانات إلى جهازك، وتؤثر في البث والتصفح وتنزيل الملفات. وسرعة الرفع هي مدى سرعة خروج البيانات من جهازك، وتؤثر في مكالمات الفيديو وإرسال الملفات الكبيرة ونشر الفيديوهات.",
                "faq.5.q": "ما هو زمن الاستجابة (Ping) وما القيمة الجيدة له؟",
                "faq.5.a": "زمن الاستجابة، ويسمى أيضًا التأخر، هو الوقت بالميلي ثانية الذي تستغرقه البيانات للوصول إلى الخادم والعودة. أقل من 20 ms ممتاز، ومن 20 إلى 50 ms جيد للألعاب والمكالمات، وأكثر من 100 ms قد يبدو بطيئًا.",
                "faq.6.q": "ما هو الاهتزاز (Jitter)؟",
                "faq.6.a": "الاهتزاز هو مقدار تغيّر زمن الاستجابة من لحظة إلى التالية. الاهتزاز المنخفض يعني اتصالًا مستقرًا. أما الاهتزاز المرتفع فيسبب تقطع مكالمات الفيديو وانقطاع الصوت وتأخر الألعاب حتى لو كانت سرعة التنزيل عالية.",
                "faq.7.q": "هل اختبار السرعة هذا مجاني؟",
                "faq.7.a": "نعم. إنه مجاني تمامًا، ولا يتطلب تسجيلًا، ويعمل على الهواتف والأجهزة اللوحية والحواسيب في أي متصفح حديث.",
                "faq.8.q": "هل يستهلك الاختبار الكثير من البيانات؟",
                "faq.8.a": "يقوم الاختبار الكامل بتنزيل ورفع بيانات اختبارية لمدة 25 ثانية تقريبًا، لذا قد يستهلك قدرًا ملحوظًا من البيانات على اتصال سريع. إذا كانت باقة الجوال لديك محدودة، فأجرِه عبر Wi-Fi أو نادرًا.",
                "seo.home.title": "اختبار سرعة الإنترنت: افحص التنزيل والرفع وزمن الاستجابة (مجاني)",
