            -- Hindi (Hin)
            N'{
                "about.h1": "इस साइट के बारे में",
                "about.p1": "thakurg.com मुफ़्त टूल्स का एक छोटा संग्रह है। होम पेज एक इंटरनेट स्पीड टेस्ट है जो पिंग, जिटर, डाउनलोड और अपलोड स्पीड नापता है। यह अंग्रेज़ी, हिंदी और अरबी में चलता है, और इसे ऐप की तरह अपने फ़ोन या कंप्यूटर पर इंस्टॉल किया जा सकता है।",
                "about.p2": "एट्रियम एचआर कर्मचारी, उपस्थिति, छुट्टी, पेरोल, भर्ती और रिपोर्ट के लिए एक डेमो वर्कस्पेस है। क्रेटा इस साइट पर रखे ट्रैक सुनने के लिए एक सरल ऑडियो प्लेयर है।",
