        (
            'privacy',
            -- English (Eng)
            N'{
                "privacy.h1": "Privacy policy",
                "privacy.p1": "This site does not ask you to sign up and does not collect personal information.",
                "privacy.p2": "Your chosen language, theme and any speed test results you save are stored in your own browser (local storage). They are never sent to our servers and you can clear them at any time.",
                "privacy.p3": "When you run a speed test, your browser connects to our own speed test server to move test data. Our server sees your IP address as part of that connection, as with any website request. The connection details and services status sections also contact ipwho.is, api4.ipify.org and api6.ipify.org (to show your IPv4 and IPv6 address) and the public status pages of the listed services. These requests go directly from your browser, and nothing is stored.",
                "privacy.p4": "The site serves its own fonts. Only the Atrium HR demo loads fonts from Google Fonts, and Google may receive your IP address when you open it.",
                "privacy.p5": "If this policy changes, the new version will be published on this page.",
                "seo.privacy.title": "Privacy Policy",
                "seo.privacy.desc": "How thakurg.com handles your data. No signup, no personal data collected, results stay in your browser."
            }',
            -- Hindi (Hin)
