                "privacy.p3": "जब आप स्पीड टेस्ट चलाते हैं, तो आपका ब्राउज़र टेस्ट डेटा भेजने-पाने के लिए हमारे अपने स्पीड टेस्ट सर्वर से जुड़ता है। किसी भी वेबसाइट अनुरोध की तरह, इस कनेक्शन में हमारा सर्वर आपका IP पता देख सकता है। कनेक्शन विवरण और सेवाओं की स्थिति वाले हिस्से ipwho.is, api4.ipify.org और api6.ipify.org (आपका IPv4 और IPv6 पता दिखाने के लिए) और सूचीबद्ध सेवाओं के सार्वजनिक स्टेटस पेज से भी जुड़ते हैं। ये अनुरोध सीधे आपके ब्राउज़र से जाते हैं और कुछ भी सहेजा नहीं जाता।",
