                "seo.privacy.title": "गोपनीयता नीति",
                "seo.privacy.desc": "thakurg.com आपके डेटा को कैसे संभालता है। साइन अप नहीं, कोई व्यक्तिगत डेटा नहीं, नतीजे आपके ब्राउज़र में रहते हैं।"
            }',
            -- Arabic (Arab)
            N'{
                "privacy.h1": "سياسة الخصوصية",
                "privacy.p1": "لا يطلب هذا الموقع منك التسجيل ولا يجمع أي معلومات شخصية.",
