                "privacy.p4": "يقدّم الموقع خطوطه بنفسه. فقط النسخة التجريبية أتريوم للموارد البشرية تحمّل الخطوط من Google Fonts، وقد تتلقى Google عنوان IP الخاص بك عند فتحها.",
