            N'{
                "seo.khata.title": "{page:khata}: मुफ़्त डिजिटल उधार खाता",
                "seo.khata.desc": "किसे पैसे देने हैं और किससे लेने हैं, इसका हिसाब रखें। सेकंडों में एंट्री जोड़ें, किसी भी मुद्रा में अलग-अलग बही रखें, आपके लॉग इन से सुरक्षित। फ़ोन और पीसी पर चलता है।",
                "khata.app.name": "{page:khata}",
                "khata.app.book": "बही",
                "khata.app.chooseBook": "बही चुनें",
                "khata.app.manageBooks": "बही प्रबंधित करें…",
                "khata.app.menu": "{page:khata} मेनू",
                "khata.app.profile": "प्रोफ़ाइल",
                "khata.back": "वापस",
                "khata.save": "सहेजें",
                "khata.cancel": "रद्द करें",
                "khata.close": "बंद करें",
                "khata.loading": "लोड हो रहा है…",
                "khata.l.h1": "{page:khata}: आपका मुफ़्त डिजिटल उधार खाता",
                "khata.l.lead": "हर \"आपने दिए\" और \"आपको मिले\" को लिखें, हर ग्राहक का बकाया एक नज़र में देखें और अपना खाता अपने लॉग इन से सुरक्षित रखें।",
                "khata.l.open": "{page:khata} खोलें",
                "khata.l.login": "लॉग इन करें",
                "khata.l.featuresH": "आप क्या कर सकते हैं",
                "khata.l.f1": "ग्राहक और सप्लायर रखें, हर एक का चालू बकाया।",
                "khata.l.f2": "तारीख और नोट के साथ \"आपने दिए\" और \"आपको मिले\" एंट्री सेकंडों में जोड़ें।",
                "khata.l.f3": "अलग-अलग बही, हर एक अपनी मुद्रा में: रुपया, दिरहम, डॉलर या आपकी अपनी।",
                "khata.l.f4": "हर ऐप के लिए एक ही thakurg.com खाता: आपकी बही केवल आप खोल सकते हैं।",
                "khata.l.f5": "हर बदलाव इतिहास में रखा जाता है, इसलिए खाते पर हमेशा भरोसा किया जा सकता है।",
                "khata.l.faqH": "सवाल",
                "khata.l.q1": "क्या {page:khata} मुफ़्त है?",
                "khata.l.q1a": "हाँ। संपर्क और एंट्री जोड़ना मुफ़्त है।",
                "khata.l.q2": "मैं लॉग इन कैसे करूँ?",
                "khata.l.q2a": "अपने thakurg.com खाते के ईमेल पते और पासवर्ड से। साइन अप मुफ़्त है।",
                "khata.l.q3": "क्या एंट्री बाद में बदली जा सकती है?",
                "khata.l.q3a": "हाँ, जिसने जोड़ी हो वही। पुराना संस्करण इतिहास में रहता है।",
                "khata.l.q4": "क्या मेरा डेटा निजी है?",
