                "tracker.l.f.charts.text": "यह महीना, पिछले छह महीने, और श्रेणी के अनुसार खर्च।",
                "tracker.l.f.privacy": "निजी रखता है।",
                "tracker.l.f.privacy.text": "अपनी प्रोफ़ाइल से कभी भी अपना डेटा डाउनलोड करें या हटाएँ।",
                "tracker.l.faqTitle": "सवाल",
                "tracker.l.q1": "क्या {app} मेरे सारे संदेश पढ़ता है?",
                "tracker.l.a1": "नहीं। सिर्फ़ उसकी सूची के बैंकों और भुगतान ऐप्स के अलर्ट। OTP, प्रचार और निजी संदेश आगे पढ़े या रखे बिना हटा दिए जाते हैं।",
                "tracker.l.q2": "क्या कोई वेबसाइट मेरे SMS पढ़ सकती है?",
                "tracker.l.a2": "नहीं। अपने-आप पढ़ने के लिए {app} Android ऐप चाहिए। तब तक आप बैंक SMS पेस्ट कर सकते हैं, वह वैसे ही पढ़ा जाता है।",
                "tracker.l.q3": "अगर {app} गलत समझे तो?",
                "tracker.l.a3": "जिस पर यह पक्का न हो, वह आपकी जाँच का इंतज़ार करता है, और आप कोई भी लेन-देन बदल, दूसरी श्रेणी में डाल, अनदेखा या हटा सकते हैं।",
                "tracker.l.q4": "क्या {app} मुफ़्त है?",
                "tracker.l.a4": "हाँ। यह आपके मुफ़्त thakurg.com खाते का हिस्सा है।",
                "tracker.l.q5": "क्या मैं अपना डेटा हटा सकता हूँ?",
                "tracker.l.a5": "हाँ। अपनी प्रोफ़ाइल पर आप इसे डाउनलोड कर सकते हैं, मूल SMS टेक्स्ट हटा सकते हैं, या {app} का रखा सब कुछ हटा सकते हैं।"
